{"meta": {"name": "sales-calc", "description": "Compute total revenue, cost, profit, margin in memory"}, "script": "const data = [
  {m:"1月", r:1000, c:700},
  {m:"2月", r:2000, c:1400},
  {m:"3月", r:3000, c:2100},
  {m:"4月", r:4000, c:2800},
  {m:"5月", r:5000, c:3500},
  {m:"6月", r:6000, c:4200},
];
const totalR = data.reduce((s,d)=>s+d.r,0);
const totalC = data.reduce((s,d)=>s+d.c,0);
const profit = totalR-totalC;
const margin = (profit/totalR*100).toFixed(1)+"%";
return {totalR, totalC, profit, margin};"}

